const api=(window.API_BASE_URL||'').replace(/\/$/,'');
const $=s=>document.querySelector(s),t=s=>I18N.t(s);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let participantPage=1,participantPages=1,participantRequest=0,eventImages=[],uploading=false,uploadEpoch=0;
const imageURL=(url,type='road')=>url?.startsWith('/uploads/')?api+url:url?.startsWith('assets/')?url:({trail:'assets/community-1.jpg',family:'assets/community-2.jpg',road:'assets/community-1.jpg'}[type]||'assets/community-1.jpg');
let csrf='',username='',events=[],editingId=null,connected=false,messagingReady=false,messagingStates={};
function status(id,message,error=false){$(id).textContent=t(message);$(id).classList.toggle('error',error)}
async function request(route,options={}){
 const response=await fetch(api+route,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(csrf?{'X-CSRF-Token':csrf}:{}),'Accept-Language':I18N.lang,...options.headers}});
 const data=await response.json();
 if(!response.ok){if(response.status===401&&route!=='/api/auth/login'){showLogin();status('#loginStatus','انتهت الجلسة، سجّل الدخول مجددًا.',true)}throw Error(t(data.error||'تعذّر تنفيذ الطلب'))}
 return data;
}
function showLogin(){participantRequest++;uploadEpoch++;if($('#editEventDialog').open)$('#editEventDialog').close();$('#participantsBody').innerHTML='';$('#adminEvents').innerHTML='';window.AdminFeatures?.reset();events=[];eventImages=[];csrf='';username='';$('#loginView').hidden=false;$('#dashboard').hidden=true;$('#password').value='';}
async function showDashboard(user){csrf=user.csrf;username=user.username;$('#loginView').hidden=true;$('#dashboard').hidden=false;$('#password').value='';$('#welcome').textContent=t('مرحبًا')+' '+username;$('#serviceStatus').textContent=t(messagingReady?'مهيّأة':'تحتاج إعدادًا');try{await refresh()}catch(e){status('#dashboardStatus',e.message,true)}}
async function refresh(){events=await request('/api/admin/events');renderEvents();window.AdminFeatures?.syncEvents();await refreshParticipants();}
function renderEvents(){
 $('#eventCount').textContent=events.length;
 $('#adminEvents').innerHTML=events.map(raw=>{const e=I18N.event(raw);return `<article class="admin-race-card"><div class="admin-race-cover"><img src="${esc(imageURL(e.images?.[0]?.url,e.type))}" alt="${esc(e.name)}" loading="lazy"><span class="badge">${esc(e.label)}</span><span class="race-cover-number">${esc(e.art)}<small>KM</small></span></div><div class="admin-race-content"><span class="date">${e.timePending?new Date(e.start).toLocaleDateString(I18N.lang)+' · '+t('ساعة الانطلاق تُعلن لاحقًا'):new Date(e.start).toLocaleString(I18N.lang)}</span><h3>${esc(e.name)}</h3><p>${esc(e.location)}</p><div class="chips">${e.distances.map(d=>`<span>${esc(I18N.distance(d))}</span>`).join('')}</div><div class="race-count"><strong>${new Intl.NumberFormat(I18N.lang).format(e.registeredCount||0)}</strong><span>${t('مشارك مسجّل')}</span></div><div class="admin-race-actions"><button class="outline-btn" data-edit="${esc(e.id)}">${t('تعديل السباق')}</button><button class="text-btn" data-participants="${esc(e.id)}">${t('عرض المشاركين')}</button></div></div></article>`}).join('')||'<p>'+t('أضف سباقك الأول لبدء التسجيل.')+'</p>';
 const selected=$('#participantRace').value;$('#participantRace').innerHTML=`<option value="">${t('كل السباقات')}</option>`+events.map(e=>`<option value="${esc(e.id)}">${esc(I18N.event(e).name)}</option>`).join('');$('#participantRace').value=selected;
}
async function refreshParticipants(){const ticket=++participantRequest;const params=new URLSearchParams({page:String(participantPage),q:$('#participantSearch').value,eventId:$('#participantRace').value});const data=await request('/api/admin/registrations?'+params);if(ticket!==participantRequest)return;participantPages=data.pages;if(participantPage>participantPages){participantPage=participantPages;return refreshParticipants()}$('#registrationCount').textContent=new Intl.NumberFormat(I18N.lang).format(data.totalActive);$('#participantsEmpty').hidden=!!data.items.length;$('#participantsBody').innerHTML=data.items.map(p=>`<tr><td>${p.bib||'—'}</td><td><strong>${esc(p.name)}</strong></td><td>${esc(events.find(e=>e.id===p.event_id)?I18N.event(events.find(e=>e.id===p.event_id)).name:p.event_id)}</td><td>${esc(I18N.distance(p.distance))}</td><td dir="ltr">${esc(p.email)}</td><td dir="ltr">${esc(p.phone)}</td><td>${t(p.state)}${p.checked_in_at?' · '+t('حضر'):''}${p.refund_due?' · '+t('يحتاج مراجعة استرداد'):''}</td>${['school','schoolClass','birthYear','nationalId','country','gender','guardianName','guardianPhone','shirtSize','guardianConsent','medicalConsent','consentAt'].map(key=>`<td class="student-detail">${esc(p.student?(key==='gender'?t(p.student[key]==='male'?'ذكر':'أنثى'):key.endsWith('Consent')?t(p.student[key]?'نعم':'لا'):key==='consentAt'?new Date(p.student[key]).toLocaleString(I18N.lang):p.student[key]??'—'):'—')}</td>`).join('')}<td>${t(p.sms_confirmation||'غير مطلوب')}</td><td>${t(p.sms_reminder||'غير مطلوب')}</td><td><button class="outline-btn" data-cancel-registration="${esc(p.id)}">${t('إلغاء المشاركة')}</button></td></tr>`).join('');$('#pageStatus').textContent=t('الصفحة')+' '+participantPage+' / '+participantPages+' · '+data.total+' '+t('مشارك مسجّل');$('#previousPage').disabled=participantPage<=1;$('#nextPage').disabled=participantPage>=participantPages;}
function loadParticipants(){refreshParticipants().catch(e=>status('#dashboardStatus',e.message,true))}
let searchTimer;$('#participantSearch').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{participantPage=1;loadParticipants()},300)});$('#participantRace').addEventListener('change',()=>{participantPage=1;loadParticipants()});$('#previousPage').addEventListener('click',()=>{if(participantPage>1){participantPage--;loadParticipants()}});$('#nextPage').addEventListener('click',()=>{if(participantPage<participantPages){participantPage++;loadParticipants()}});
function renderImages(){ $('#imagePreviews').innerHTML=eventImages.map((image,i)=>`<figure><img src="${esc(imageURL(image.url))}" alt="${t('صور الماراثون')}"><figcaption>${i===0?t('الغلاف'):t('صورة')+' '+(i+1)}</figcaption><div><button type="button" data-remove-image="${esc(image.id)}">${t('إزالة')}</button>${i?`<button type="button" data-cover-image="${esc(image.id)}">${t('تعيين كغلاف')}</button>`:''}</div></figure>`).join('') }
$('#imagePreviews').addEventListener('click',e=>{if(uploading)return;const remove=e.target.closest('[data-remove-image]'),cover=e.target.closest('[data-cover-image]');if(remove)eventImages=eventImages.filter(i=>i.id!==remove.dataset.removeImage);if(cover){const index=eventImages.findIndex(i=>i.id===cover.dataset.coverImage);if(index>=0)eventImages.unshift(...eventImages.splice(index,1))}renderImages()});
$('#imageUpload').addEventListener('change',async e=>{const files=[...e.target.files],epoch=uploadEpoch;e.target.value='';if(!files.length)return;if(eventImages.length+files.length>6){status('#imageStatus','يمكنك إضافة 6 صور كحد أقصى.',true);return}if(files.some(f=>f.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type))){status('#imageStatus','اختر صور JPG أو PNG أو WebP أصغر من 5 ميغابايت.',true);return}uploading=true;$('#saveEvent').disabled=true;$('#imageUpload').disabled=true;status('#imageStatus','جارٍ رفع الصور…');try{for(const file of files){const image=await request('/api/admin/uploads',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});if(epoch!==uploadEpoch)return;eventImages.push(image);renderImages()}status('#imageStatus','تم رفع الصور. احفظ السباق لنشرها.')}catch(err){if(epoch===uploadEpoch)status('#imageStatus',err.message,true)}finally{uploading=false;$('#saveEvent').disabled=false;$('#imageUpload').disabled=false}});
$('#togglePassword').addEventListener('click',()=>{const show=$('#password').type==='password';$('#password').type=show?'text':'password';$('#togglePassword').textContent=t(show?'إخفاء':'إظهار');$('#togglePassword').setAttribute('aria-pressed',String(show));$('#togglePassword').setAttribute('aria-label',t(show?'إخفاء كلمة المرور':'إظهار كلمة المرور'))});
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();if(!connected){status('#loginStatus','شغّل الخادم المرفق لتسجيل الدخول. هذه الصفحة معاينة فقط.',true);return}const button=e.target.querySelector('[type=submit]');button.disabled=true;status('#loginStatus','جارٍ تسجيل الدخول…');try{const f=new FormData(e.target);await showDashboard(await request('/api/auth/login',{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password')})}));status('#loginStatus','')}catch(err){status('#loginStatus',err.message,true);$('#password').value=''}finally{button.disabled=false}});
$('#logout').addEventListener('click',async()=>{try{await request('/api/auth/logout',{method:'POST',body:'{}'});showLogin();status('#loginStatus','تم تسجيل الخروج.')}catch(e){status('#dashboardStatus',e.message,true)}});
function selectTab(name){['events','participants','volunteers','operations','statistics'].forEach(key=>{const selected=key===name;$('#'+key+'Panel').hidden=!selected;$('#'+key+'Tab').classList.toggle('active',selected);$('#'+key+'Tab').setAttribute('aria-selected',String(selected))});if(name==='volunteers')window.AdminFeatures?.refreshVolunteers();if(name==='statistics')window.AdminFeatures?.refreshStats();if(name!=='operations')window.AdminFeatures?.stopScanner()}
$('#eventsTab').addEventListener('click',()=>selectTab('events'));$('#participantsTab').addEventListener('click',()=>selectTab('participants'));
$('#refreshRegistrations').addEventListener('click',async()=>{try{await refresh();status('#dashboardStatus','تم تحديث المشاركات.')}catch(e){status('#dashboardStatus',e.message,true)}});
function openEvent(event=null){uploadEpoch++;eventImages=[...(event?.images||[])];renderImages();status('#imageStatus','');editingId=event?.id||null;const form=$('#eventForm');form.reset();window.AdminFeatures?.openEvent(event);status('#eventFormStatus','');$('#eventFormTitle').textContent=t(event?'تعديل السباق':'إضافة سباق');if(form.elements.timePending)form.elements.timePending.checked=event?.timePending===true;if(form.elements.feeILS){form.elements.feeILS.disabled=event?.registrationProfile==='student';if(event?.registrationProfile==='student')form.elements.feeILS.value=0}if(event){for(const name of ['name','location','description','type','art'])form.elements[name].value=event[name]||'';const d=new Date(event.start);form.elements.start.value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);form.elements.distances.value=event.distances.join('، ');for(const lang of ['he','en']){const translated=event.translations?.[lang]||(event.sample?RACE_EVENTS.find(e=>e.id===event.id)?.translations?.[lang]:{})||{};for(const field of ['name','location','description'])form.elements[lang+'_'+field].value=translated[field]||''}}$('#editEventDialog').showModal()}
$('#addEvent').addEventListener('click',()=>openEvent());$('#adminEvents').addEventListener('click',e=>{const b=e.target.closest('[data-edit]');if(b)openEvent(events.find(x=>x.id===b.dataset.edit));const list=e.target.closest('[data-participants]');if(list){$('#participantRace').value=list.dataset.participants;participantPage=1;selectTab('participants');loadParticipants()}});$('#editEventDialog .close').addEventListener('click',()=>$('#editEventDialog').close());
$('#eventForm').addEventListener('submit',async e=>{e.preventDefault();if(uploading||window.AdminFeatures?.busy)return;const f=new FormData(e.target);const payload=Object.fromEntries(f);payload.timePending=f.has('timePending');payload.feesPending=false;payload.imageIds=eventImages.filter(i=>i.id).map(i=>i.id);Object.assign(payload,window.AdminFeatures?.eventPayload()||{});delete payload.routeText;delete payload.feeILS;payload.start=new Date(payload.start).toISOString();payload.distances=payload.distances.split(/[,،]/).map(x=>x.trim()).filter(Boolean);payload.translations={};for(const lang of ['he','en']){payload.translations[lang]={};for(const field of ['name','location','description']){payload.translations[lang][field]=payload[lang+'_'+field];delete payload[lang+'_'+field]}}$('#saveEvent').disabled=true;status('#eventFormStatus','جارٍ الحفظ…');try{await request('/api/admin/events'+(editingId?'/'+encodeURIComponent(editingId):''),{method:editingId?'PUT':'POST',body:JSON.stringify(payload)});$('#editEventDialog').close();await refresh();status('#dashboardStatus','تم حفظ السباق. سيظهر للزوار عند تحديث الموقع.')}catch(err){status('#eventFormStatus',err.message,true)}finally{$('#saveEvent').disabled=false}});
(async()=>{try{const health=await request('/api/health');if(health.app!=='khotwa')throw Error();connected=true;if($('#smsServiceNotice')){$('#smsServiceNotice').dataset.ready=String(health.smsReady===true);$('#smsServiceNotice').textContent=t(health.smsReady?'خدمة SMS مهيّأة؛ القبول من المزوّد لا يؤكد التسليم.':'خدمة SMS تنتظر إعداد الحساب؛ الرسائل الموافق عليها تبقى في الطابور.')}messagingStates=health.messagingByLanguage||{};messagingReady=messagingStates[I18N.lang]??health.messagingReady;$('#connectionNotice').hidden=true;$('#setupHint').hidden=false;try{const user=await request('/api/auth/me');await showDashboard(user)}catch{status('#loginStatus','')}}catch{$('#connectionNotice').textContent=t('نسخة معاينة. تشغيل الخادم المرفق يفعّل الدخول ولوحة الإدارة.');$('#setupHint').hidden=false}})();

window.addEventListener('languagechange',()=>{messagingReady=messagingStates[I18N.lang]??false;if(!$('#dashboard').hidden){renderEvents();refreshParticipants().catch(e=>status('#dashboardStatus',e.message,true));$('#welcome').textContent=t('مرحبًا')+' '+username;$('#serviceStatus').textContent=t(messagingReady?'مهيّأة':'تحتاج إعدادًا')}if(!connected)$('#connectionNotice').textContent=t('نسخة معاينة. تشغيل الخادم المرفق يفعّل الدخول ولوحة الإدارة.');$('#togglePassword').textContent=t($('#password').type==='password'?'إظهار':'إخفاء');$('#togglePassword').setAttribute('aria-label',t($('#password').type==='password'?'إظهار كلمة المرور':'إخفاء كلمة المرور'));renderImages();$('#eventFormTitle').textContent=t(editingId?'تعديل السباق':'إضافة سباق');['#loginStatus','#dashboardStatus','#eventFormStatus'].forEach(id=>$(id).textContent='')});

window.Admin={request,status,selectTab,refresh,get events(){return events},get connected(){return connected}};

setInterval(()=>{if(connected&&!document.hidden&&!$('#dashboard').hidden&&!$('#participantsPanel').hidden)loadParticipants()},15000);

window.addEventListener('languagechange',()=>{const el=$('#smsServiceNotice');if(el)el.textContent=t(el.dataset.ready==='true'?'خدمة SMS مهيّأة؛ القبول من المزوّد لا يؤكد التسليم.':'خدمة SMS تنتظر إعداد الحساب؛ الرسائل الموافق عليها تبقى في الطابور.')});
